<style>
:root{
  --ink:#08182F;
  --navy:#003478;
  --blue:#1A6FC4;
  --blue-bright:#0057B8;
  --paper:#FFFFFF;
  --mist:#F2F5FA;
  --line:#D6E0EE;
  --line-strong:#B4C6DE;
  --text:#222222;
  --muted:#5A6B82;
  --maxw:1140px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
body{
  margin:0;background:var(--paper);color:var(--text);
  font-family:"IBM Plex Sans",system-ui,-apple-system,sans-serif;
  font-size:16px;line-height:1.65;-webkit-font-smoothing:antialiased;
}
h1,h2,h3,h4{font-family:"Archivo",system-ui,sans-serif;margin:0;line-height:1.12;letter-spacing:-0.02em;color:var(--ink)}
p{margin:0 0 1em}
a{color:var(--blue-bright)}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 24px}
.mono{font-family:"IBM Plex Mono",ui-monospace,monospace;font-variant-numeric:tabular-nums}

/* ── eyebrow / dimension label ─────────────────────────── */
.eyebrow{
  font-family:"IBM Plex Mono",monospace;font-size:11.5px;letter-spacing:.18em;
  text-transform:uppercase;color:var(--blue);margin:0 0 14px;display:flex;align-items:center;gap:10px;
}
.eyebrow::after{content:"";flex:1;height:1px;background:var(--line);max-width:120px}
.dark .eyebrow{color:#7FB2E8}
.dark .eyebrow::after{background:rgba(255,255,255,.18)}

/* ── timeline ─────────────────────────────────────────── */
section.dark .tablewrap{border-color:rgba(255,255,255,.2)}
section.dark table tbody tr:nth-child(even){background:rgba(255,255,255,.04)}
section.dark table tbody tr:hover{background:rgba(255,255,255,.08)}
section.dark table td{color:#DCE7F4;border-bottom-color:rgba(255,255,255,.13)}
section.dark table td.name{color:#7FB2E8}
ol.timeline{list-style:none;margin:34px 0 22px;padding:0;counter-reset:tl}
ol.timeline li{display:grid;grid-template-columns:86px 1fr;gap:22px;padding:20px 0;border-top:1px solid rgba(255,255,255,.14);align-items:start}
ol.timeline li:last-child{border-bottom:1px solid rgba(255,255,255,.14)}
.tl-pct{font-family:"Archivo";font-weight:800;font-size:26px;color:#5FA3E8;letter-spacing:-.03em;line-height:1;padding-top:2px}
.tl-body h4{font-size:17px;color:#fff;margin-bottom:5px}
.tl-body p{font-size:14px;color:#A9C2DC;margin:0;line-height:1.55;max-width:74ch}
@media(max-width:600px){ol.timeline li{grid-template-columns:1fr;gap:8px}}

/* ── faq ──────────────────────────────────────────────── */
.faq{margin-top:32px;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{
  cursor:pointer;list-style:none;padding:18px 40px 18px 0;position:relative;
  font-family:"Archivo";font-weight:600;font-size:17px;color:var(--ink);
}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{
  content:"+";position:absolute;right:8px;top:15px;font-family:"IBM Plex Mono";
  font-size:22px;color:var(--blue);font-weight:400;line-height:1;
}
.faq details[open] summary::after{content:"−"}
.faq summary:hover{color:var(--blue-bright)}
.faq .ans{padding:0 40px 20px 0;font-size:15px;color:#3B4A5E;max-width:78ch}
.faq .ans p{margin:0 0 .8em}
.faq .ans p:last-child{margin:0}

/* ── cities ───────────────────────────────────────────── */
.citygrid{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin-top:30px}
.citycell{background:#fff;padding:18px 16px}
.citycell b{display:block;font-family:"Archivo";font-weight:700;font-size:15.5px;color:var(--navy);margin-bottom:4px}
.citycell span{font-size:12.5px;color:var(--muted);line-height:1.45;display:block}
@media(max-width:900px){.citygrid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:560px){.citygrid{grid-template-columns:repeat(2,1fr)}}

/* ── header ───────────────────────────────────────────── */
header.bar{
  position:sticky;top:0;z-index:50;background:rgba(8,24,47,.94);
  backdrop-filter:blur(10px);border-bottom:1px solid rgba(255,255,255,.1);
}
.bar .wrap{display:flex;align-items:center;gap:24px;height:62px}
.logo{display:flex;align-items:baseline;gap:9px;color:#fff;text-decoration:none;font-family:"Archivo";font-weight:800;font-size:19px;letter-spacing:-.01em}
.logo span{font-family:"IBM Plex Mono";font-weight:400;font-size:10.5px;letter-spacing:.16em;color:#8FB8E4;text-transform:uppercase}
nav.links{margin-left:auto;display:flex;gap:22px}
nav.links a{color:#C9DAF0;text-decoration:none;font-size:13.5px;font-weight:500}
nav.links a:hover{color:#fff}
.btn{
  display:inline-block;background:var(--blue-bright);color:#fff;text-decoration:none;
  font-weight:600;font-size:14px;padding:11px 20px;border-radius:2px;border:1px solid var(--blue-bright);
  transition:background .18s ease;
}
.btn:hover{background:#0068D8;border-color:#0068D8}
.btn.ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.4)}
.btn.ghost:hover{background:rgba(255,255,255,.1)}
@media(max-width:900px){nav.links{display:none}}

/* ── hero ─────────────────────────────────────────────── */
.hero{
  background:var(--ink);color:#EAF1FA;padding:76px 0 0;position:relative;overflow:hidden;
}
.hero::before{
  content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;
  background-image:linear-gradient(rgba(122,166,220,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(122,166,220,.09) 1px,transparent 1px);
  background-size:44px 44px;
  mask-image:radial-gradient(ellipse 90% 70% at 70% 20%,#000,transparent 75%);
  -webkit-mask-image:radial-gradient(ellipse 90% 70% at 70% 20%,#000,transparent 75%);
}
.hero .wrap{position:relative}
.hero h1{
  color:#fff;font-size:clamp(38px,6.2vw,72px);font-weight:800;max-width:15ch;margin:0 0 20px;
}
.hero h1 em{font-style:normal;color:#5FA3E8}
.hero .lede{font-size:clamp(16px,2vw,19px);color:#B7CBE2;max-width:60ch;margin-bottom:34px}
.year-tag{
  display:inline-block;font-family:"IBM Plex Mono";font-size:12px;letter-spacing:.2em;
  border:1px solid rgba(127,178,232,.45);color:#9FC6EC;padding:6px 12px;margin-bottom:26px;
}

/* rate plates */
.rates{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;background:rgba(255,255,255,.14);margin-top:8px;border:1px solid rgba(255,255,255,.14)}
.rate{background:var(--ink);padding:26px 24px}
.rate.opt .val{font-size:clamp(22px,2.6vw,27px)}
.rate.opt .val + .val{margin-top:10px}
@media(max-width:980px){.rates{grid-template-columns:repeat(2,minmax(0,1fr))}.rate.opt{grid-column:1 / -1}}
.rate .lbl{font-family:"IBM Plex Mono";font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#8FB8E4;margin-bottom:10px}
.rate .val{font-family:"Archivo";font-weight:800;font-size:clamp(30px,4.6vw,44px);color:#fff;line-height:1;letter-spacing:-.03em}
.rate .val small{font-family:"IBM Plex Mono";font-weight:400;font-size:13px;color:#9FC6EC;letter-spacing:0;margin-left:6px}
.rate .sub{font-size:13.5px;color:#A9C2DC;margin-top:8px}
@media(max-width:620px){.rates{grid-template-columns:1fr}}

.citystrip{
  margin-top:56px;border-top:1px solid rgba(255,255,255,.13);padding:16px 0 20px;
  display:flex;flex-wrap:wrap;gap:8px 20px;align-items:center;
}
.citystrip b{font-family:"IBM Plex Mono";font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#7FB2E8;font-weight:500}
.citystrip span{font-size:13.5px;color:#AFC7E0}

/* ── sections ─────────────────────────────────────────── */
section{padding:78px 0;border-top:1px solid var(--line)}
section.tint{background:var(--mist)}
section.dark{background:var(--ink);color:#DCE7F4;border-top:none}
section.dark h2,section.dark h3{color:#fff}
h2{font-size:clamp(27px,3.7vw,40px);font-weight:700;margin-bottom:16px}
h3{font-size:19px;font-weight:700;margin-bottom:10px}
.section-lede{font-size:17px;color:var(--muted);max-width:66ch}
.dark .section-lede{color:#A9C2DC}

/* ── estimator (signature) ────────────────────────────── */
.est{display:grid;grid-template-columns:1.05fr 1fr;gap:0;border:1px solid var(--line-strong);background:#fff;margin-top:34px}
.est-controls{padding:30px;border-right:1px solid var(--line)}
.est-out{padding:30px;background:var(--ink);color:#fff}
@media(max-width:880px){.est{grid-template-columns:1fr}.est-controls{border-right:none;border-bottom:1px solid var(--line)}}

.ctrl-label{font-family:"IBM Plex Mono";font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);margin:0 0 10px;display:block}
.chips{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:24px}
.chip{
  font-family:"IBM Plex Mono";font-size:13px;padding:9px 13px;border:1px solid var(--line-strong);
  background:#fff;color:var(--navy);cursor:pointer;border-radius:2px;transition:all .15s ease;
}
.chip:hover{border-color:var(--blue)}
.chip[aria-pressed="true"]{background:var(--navy);border-color:var(--navy);color:#fff}
.chip:focus-visible,.seg button:focus-visible,input:focus-visible,.tab:focus-visible,a:focus-visible,button:focus-visible{outline:2px solid var(--blue);outline-offset:2px}

.field{margin-bottom:22px}
.field input[type=number]{
  width:100%;font-family:"IBM Plex Mono";font-size:19px;padding:12px 14px;
  border:1px solid var(--line-strong);border-radius:2px;color:var(--ink);background:#fff;
}
.field .hint{font-size:12.5px;color:var(--muted);margin-top:7px}
.seg{display:flex;border:1px solid var(--line-strong);border-radius:2px;overflow:hidden}
.seg button{
  flex:1;padding:11px 8px;background:#fff;border:0;border-right:1px solid var(--line);
  font-family:"IBM Plex Sans";font-size:13.5px;font-weight:500;color:var(--navy);cursor:pointer;
}
.seg button:last-child{border-right:0}
.seg button[aria-pressed="true"]{background:var(--blue-bright);color:#fff}

.plotdraw{margin-top:8px;border-top:1px dashed var(--line-strong);padding-top:18px}
.plotdraw svg{width:100%;height:auto;max-height:210px;display:block}

/* estimator output */
.out-row{display:flex;justify-content:space-between;align-items:baseline;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.13);gap:12px}
.out-row .k{font-size:14px;color:#A9C2DC}
.out-row .k em{font-style:normal;display:block;font-family:"IBM Plex Mono";font-size:11px;color:#7FA0C4;letter-spacing:.05em}
.out-row .v{font-family:"IBM Plex Mono";font-size:17px;color:#fff;white-space:nowrap}
.total{margin-top:22px;padding-top:20px;border-top:2px solid var(--blue)}
.total .k{font-family:"IBM Plex Mono";font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#8FB8E4;margin-bottom:8px}
.total .big{font-family:"Archivo";font-weight:800;font-size:clamp(30px,4.4vw,42px);letter-spacing:-.03em;line-height:1.05;color:#fff}
.total .alt{font-family:"IBM Plex Mono";font-size:14px;color:#7FB2E8;margin-top:8px}
.split{display:flex;height:8px;margin:20px 0 8px;background:rgba(255,255,255,.12)}
.split i{display:block;height:100%}
.split .g{background:#5FA3E8}
.split .f{background:#0057B8}
.legend{display:flex;gap:18px;font-size:12px;color:#A9C2DC;font-family:"IBM Plex Mono"}
.legend s{text-decoration:none;display:inline-block;width:9px;height:9px;margin-right:6px}
.disclaim{font-size:12px;color:#7FA0C4;margin-top:22px;line-height:1.55}

/* ── tables ───────────────────────────────────────────── */
.tablewrap{overflow-x:auto;border:1px solid var(--line-strong);background:#fff;margin-top:30px}
table{width:100%;border-collapse:collapse;min-width:620px}
th,td{padding:14px 16px;text-align:left;border-bottom:1px solid var(--line);font-size:14.5px}
thead th{
  background:var(--navy);color:#fff;font-family:"IBM Plex Mono";font-size:11px;
  letter-spacing:.13em;text-transform:uppercase;font-weight:500;border-bottom:0;
}
tbody tr:nth-child(even){background:#F7FAFD}
tbody tr:hover{background:#EDF3FA}
td.num,th.num{text-align:right;font-family:"IBM Plex Mono";font-variant-numeric:tabular-nums}
td.name{font-weight:600;color:var(--navy);white-space:nowrap}
tfoot td{background:var(--mist);font-weight:600;color:var(--navy);border-bottom:0}
.tbl-note{font-size:12.5px;color:var(--muted);margin-top:12px}

/* ── scope cards ──────────────────────────────────────── */
.two{display:grid;grid-template-columns:repeat(2,1fr);gap:24px;margin-top:34px}
@media(max-width:820px){.two{grid-template-columns:1fr}}
.card{border:1px solid var(--line-strong);background:#fff;padding:28px}
.card .price{font-family:"Archivo";font-weight:800;font-size:32px;color:var(--navy);letter-spacing:-.03em;margin:6px 0 4px}
.card .price small{font-family:"IBM Plex Mono";font-size:12px;font-weight:400;color:var(--muted);letter-spacing:0;margin-left:6px}
ul.check{list-style:none;padding:0;margin:18px 0 0;columns:2;column-gap:22px}
ul.check li{font-size:14px;padding:5px 0 5px 22px;position:relative;break-inside:avoid;color:#3B4A5E}
ul.check li::before{
  content:"";position:absolute;left:0;top:12px;width:11px;height:2px;background:var(--blue);
}
@media(max-width:520px){ul.check{columns:1}}

/* ── variables grid ───────────────────────────────────── */
.grid3{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin-top:32px}
.grid3 .cell{background:#fff;padding:22px 20px}
.grid3 .cell .n{font-family:"IBM Plex Mono";font-size:11px;color:var(--blue);letter-spacing:.12em;margin-bottom:9px}
.grid3 .cell h4{font-size:15.5px;font-weight:700;margin-bottom:6px}
.grid3 .cell p{font-size:13.5px;color:var(--muted);margin:0;line-height:1.5}
@media(max-width:900px){.grid3{grid-template-columns:repeat(2,1fr)}}
@media(max-width:520px){.grid3{grid-template-columns:1fr}}

/* ── brands ───────────────────────────────────────────── */
.tabs{display:flex;flex-wrap:wrap;gap:6px;margin-top:30px}
.tab{
  font-size:13.5px;font-weight:500;padding:9px 15px;background:#fff;border:1px solid var(--line-strong);
  color:var(--navy);cursor:pointer;border-radius:2px;
}
.tab[aria-selected="true"]{background:var(--navy);color:#fff;border-color:var(--navy)}
.brandgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin-top:22px}
@media(max-width:880px){.brandgrid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.brandgrid{grid-template-columns:1fr}}
.brand{background:#fff;padding:20px}
.brand h4{font-size:14px;font-weight:700;color:var(--navy);margin-bottom:10px;text-transform:uppercase;letter-spacing:.04em;font-family:"IBM Plex Sans"}
.brand ul{list-style:none;margin:0;padding:0}
.brand li{font-size:14px;color:#3B4A5E;padding:3px 0}
.brand li b{font-weight:600;color:var(--blue-bright);font-family:"IBM Plex Mono";font-size:10px;letter-spacing:.08em;margin-left:6px;vertical-align:1px}

/* ── why acco ─────────────────────────────────────────── */
.caps{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.14);margin-top:34px}
.cap{background:var(--ink);padding:24px 22px}
.cap .n{font-family:"IBM Plex Mono";font-size:11px;color:#5FA3E8;letter-spacing:.14em;margin-bottom:10px}
.cap h4{font-size:16px;color:#fff;margin-bottom:6px}
.cap p{font-size:13.5px;color:#A9C2DC;margin:0;line-height:1.55}
@media(max-width:880px){.caps{grid-template-columns:repeat(2,1fr)}}
@media(max-width:520px){.caps{grid-template-columns:1fr}}

/* ── CTA ──────────────────────────────────────────────── */
.cta{background:var(--navy);color:#fff;padding:70px 0;border-top:none}
.cta h2{color:#fff;max-width:18ch}
.cta .services{display:flex;flex-wrap:wrap;gap:8px;margin:26px 0 34px}
.cta .services span{border:1px solid rgba(255,255,255,.32);padding:7px 13px;font-size:13.5px;color:#DCE7F4;border-radius:2px}
.ctagrid{display:grid;grid-template-columns:1.1fr 1fr;gap:44px;align-items:start}
@media(max-width:820px){.ctagrid{grid-template-columns:1fr;gap:30px}}
.contact{border:1px solid rgba(255,255,255,.28);padding:26px}
.contact dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:10px 18px;font-size:14.5px}
.contact dt{font-family:"IBM Plex Mono";font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#9FC6EC;padding-top:4px}
.contact dd{margin:0;color:#fff}
.contact a{color:#fff;text-decoration:none;border-bottom:1px solid rgba(255,255,255,.4)}
.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}

footer{background:var(--ink);color:#7FA0C4;padding:34px 0;font-size:13px;border-top:1px solid rgba(255,255,255,.1)}
footer .wrap{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center}
footer b{color:#C9DAF0;font-weight:600}


/* ══ QUOTATION DOCUMENT ══════════════════════════════════ */
.quote-toolbar{
  position:sticky;top:0;z-index:80;background:var(--ink);color:#fff;
  padding:12px 0;border-bottom:1px solid rgba(255,255,255,.15);
}
.quote-toolbar .wrap{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.quote-toolbar .ttl{font-family:"IBM Plex Mono";font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#8FB8E4;margin-right:auto}
.quote-stage{background:#E8EDF3;padding:26px 16px 60px}
.quote-doc{
  width:210mm;max-width:100%;margin:0 auto;background:#fff;color:#1A1A1A;
  min-height:297mm;
  padding:16mm 15mm;box-shadow:0 2px 24px rgba(0,40,90,.16);
  font-size:11.2px;line-height:1.5;
}
.quote-doc *{box-sizing:border-box}

.lh{display:flex;align-items:flex-start;gap:20px;padding-bottom:12px;border-bottom:3px solid var(--navy)}
