    font-size:10.2px;transform:none!important;
  }
  body.quote-mode .quote-stage{margin:0!important;border:0!important}
  body.quote-mode table.qt,body.quote-mode table.spec{table-layout:fixed;width:100%!important}
  body.quote-mode table.qt td,body.quote-mode table.spec td{word-wrap:break-word;overflow-wrap:anywhere}
  .qsection,.sign,.qto{page-break-inside:avoid}
  .lh,table.qt thead th,table.qt tr.grand td,.qsection > h2{-webkit-print-color-adjust:exact;print-color-adjust:exact}
}

/* ── print ────────────────────────────────────────────── */
@media print{
  header.bar,.actions,.est-controls .seg,.printhide{display:none!important}
