<script>

(function(){
  "use strict";

  // calculation engine — public/js/commercial-plaza-calc.js; every figure comes from C.estimate()
  var C = window.PlazaCalc;
  var STD = C.STD, DESIGN = C.DESIGN, MAX = C.MAX, CITIES = C.CITIES, AUTHS = C.AUTHS, DHA_PLOTS = C.DHA_PLOTS,
      TL = C.TL, DESIGN_STAGES = C.DESIGN_STAGES, ADDONS = C.ADDONS;
  var fmt = C.fmt, num = C.num, ordinal = C.ordinal, extend = C.extend, byId = C.byId, configStr = C.configStr,
      defMumty = C.defMumty, sizeName = C.sizeName, cityRates = C.cityRates, dims = C.dims, rowsOf = C.rowsOf,
      sumAreas = C.sumAreas, levelName = C.levelName, finRates = C.finRates, costOf = C.costOf,
      designFeeOf = C.designFeeOf, optOf = C.optOf, addonCtx = C.addonCtx, durOf = C.durOf,
      payStages = C.payStages, stageAmounts = C.stageAmounts, estimate = C.estimate;

  var PRESETS = [
    {id:"4m", label:"4 Marla", w:30, d:30},  {id:"5m", label:"5 Marla", w:25, d:45},
    {id:"8m", label:"8 Marla", w:30, d:60},  {id:"10m", label:"10 Marla", w:35, d:65},
    {id:"16m", label:"16 Marla", w:60, d:60}, {id:"1k", label:"1 Kanal", w:50, d:90},
    {id:"32m", label:"32 Marla", w:60, d:120}, {id:"2k", label:"2 Kanal", w:75, d:120},
    {id:"4k", label:"4 Kanal", w:150, d:120}
  ];

  var DELIVERABLES = [
    "Site survey and bylaw study — coverage, height and floors for the society",
    "Concept — zoning, shop and office layouts, stair and lift core, parking",
    "3D elevation and renders",
    "Submission drawings to the authority's required scales",
    "Architectural working drawings — plans, sections, elevations, schedules, facade and stair details",
    "Structural drawings — foundation, column schedule, beams, slabs, retaining walls, reinforcement schedules and calculations",
    "MEP drawings — power, lighting, DB schedules and load calculation, plumbing and drainage, water tanks, fire alarm and fire fighting, ventilation",
    "Architect's and structural stability certificates, electrical and mechanical engineers' certificates",
    "AutoCAD soft copy and 3D views under the architect's seal",
    "Approval follow-up and replies to the authority's observations"
  ];


  var BRANDS = {
    "Structure": [
      {t:"Cement", v:["Maple Leaf","Bestway","DG Khan","Lucky","Fauji"]},
      {t:"Steel — Grade 60", v:["Amreli Steels|60,000 PSI","Mughal Steel|60,000 PSI","Agha Steel|60,000 PSI"]},
      {t:"Concrete", v:["Ready-mix, 4,000 psi","28-day cube tests per pour"]},
      {t:"Waterproofing", v:["Sika Pakistan","Master Builders (BASF)","Fosroc"]},
      {t:"Masonry", v:["A-class kiln bricks","Concrete blocks"]}
    ],
    "Facade & glazing": [
      {t:"Aluminium systems", v:["Schüco|IMPORTED","Reynaers|IMPORTED","Chawla Aluminium","Prime Aluminium","Alcop"]},
      {t:"Glass", v:["Ghani Glass","Tariq Glass","AGC","Saint-Gobain"]},
      {t:"ACP", v:["Alucobond","Alpolic","Alstrong|FR CORE"]},
      {t:"Cladding", v:["Local marble and granite","Master porcelain","Stile porcelain"]}
    ],
    "Electrical & power": [
      {t:"Cables", v:["Pakistan Cables","Newage Cables","Fast Cables"]},
      {t:"Switchgear", v:["Siemens","ABB","Schneider","Terasaki"]},
      {t:"Transformers", v:["PEL","Siemens Pakistan","Transfopower","Elmetec"]},
      {t:"Generators", v:["Cummins","Perkins","Caterpillar","FG Wilson"]},
      {t:"Solar", v:["Longi","Jinko","JA Solar","Huawei inverters","Growatt inverters"]}
    ],
    "Lifts & escalators": [
      {t:"Lifts — international", v:["Otis","Kone","Schindler","Mitsubishi Electric","Hitachi"]},
      {t:"Lifts — mid-range", v:["Fuji","Hyundai","Sigma","Star Elevator"]},
      {t:"Escalators", v:["Otis","Kone","Schindler","Mitsubishi","Hitachi"]}
    ],
    "Fire & safety": [
      {t:"Fire alarm", v:["Notifier / Honeywell","Siemens","Bosch","GST"]},
      {t:"Sprinklers", v:["Viking","Tyco","Reliable"]},
      {t:"Fire pumps", v:["Grundfos","KSB Pakistan","Ebara"]},
      {t:"Hydrants and cabinets", v:["Naffco","Local cabinet makers"]},
      {t:"CCTV and access", v:["Hikvision","Dahua","Uniview","ZKTeco","HID"]}
    ],
    "HVAC & finishes": [
      {t:"HVAC / VRF", v:["Daikin","Mitsubishi Electric","Gree","Haier","Midea"]},
      {t:"Floor tiles", v:["Master Tiles","Shabbir Tiles","Stile"]},
      {t:"Paint", v:["ICI Dulux","Berger Paints","Nippon Paint"]},
