      {t:"Sanitary ware", v:["Porta","Sonex","Grohe|PREMIUM"]}
    ]
  };
  // which part of the contract each category belongs to, for the quotation
  var BRAND_SCOPES = {
    "Structure":          {gray:true},
    "Facade & glazing":   {fin:true, ads:["facade"]},
    "Electrical & power": {fin:true, ads:["gen","trans","solar"]},
    "Lifts & escalators": {ads:["lift"]},
    "Fire & safety":      {ads:["falarm","fhose","sprink","fpump","cctv"]},
    "HVAC & finishes":    {fin:true, ads:["vrf"]}
  };

  // ── formatting ────────────────────────────────
  function rs(n){ return "Rs " + fmt(n); }
  // quantities and rates keep up to 2 decimals so quantity × rate visibly equals the rounded amount
  function qty(n){ return (Math.round(n*100)/100).toLocaleString("en-US", {maximumFractionDigits:2}); }
  function sft(n){ return qty(n) + " SFT"; }
  function words(n){
    if(n >= 10000000) return "≈ Rs " + (n/10000000).toFixed(2) + " Crore";
    if(n >= 100000)   return "≈ Rs " + (n/100000).toFixed(2) + " Lakh";
    return "";
  }
  function crore(n){ return "Rs " + (n/10000000).toFixed(2) + " crore"; }
  function months(d){ return (Math.round(d/30*2)/2).toString(); }
  function pctTxt(p){ return (Math.round(p*10)/10) + "%"; }
  function esc(s){
    return String(s == null ? "" : s).replace(/[&<>"]/g, function(c){
      return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];
    });
  }

  // ── state ─────────────────────────────────────
  var state = {
    city:"lhr", auth:"dha", preset:"8m", w:30, d:60,
    cov:extend(AUTHS[0].cov, {}), mumty:275, mumtyEdited:false,
    b:1, m:true, u:4, lmr:true, clear:0, setback:0, applied:null, over:{},
    bmtUse:"shop", scope:"turnkey", level:"std",
    design:true, customRates:false,
    rates:extend(STD, {}), dr:extend(DESIGN, {}), ads:{}
  };
  ADDONS.forEach(function(ad){ state.ads[ad.id] = {on:false, qty:null, rate:null, opt:ad.defOpt || null}; });

  function cityObj(){ return byId(CITIES, state.city); }
  function authObj(){ return byId(AUTHS, state.auth); }
  function rates(){ return state.customRates ? state.rates : cityRates(cityObj()); }
  function dRates(){ return state.customRates ? state.dr : DESIGN; }
  function plotLabel(){
    var p = state.preset ? byId(PRESETS, state.preset) : null;
    return p && p.id === state.preset ? p.label : sizeName(state.w * state.d);
  }


  function cfgNow(){
    return {w:state.w, d:state.d, label:plotLabel(), cov:state.cov, mumty:state.mumty, lmr:state.lmr,
            b:state.b, m:state.m, u:state.u, clear:state.clear, setback:state.setback, over:state.over,
            bmtUse:state.bmtUse, scope:state.scope, level:state.level, rates:rates(),
            design:state.design, dr:dRates(), ads:state.ads,
            auth:authObj(), city:cityObj(), applied:state.applied};
  }
  // full DHA envelope for a reference plot and phase
  function dhaCfg(p, ph, extra){
    return extend({w:p.w, d:p.d, label:p.label, cov:AUTHS[0].cov, mumty:defMumty(p.w*p.d), lmr:true,
                   b:ph.b, m:ph.m, u:ph.u, clear:ph.clear || 0, setback:ph.setback || 0, over:null,
                   bmtUse:"shop", scope:"turnkey", level:"std", rates:rates(), design:false,
                   dr:dRates(), ads:{}, auth:AUTHS[0], city:cityObj(), applied:null}, extra || {});
  }


  // DHA reference plot matching the current plot area, if any
  function dhaMatch(){
    var A = state.w * state.d;
    for(var i=0;i<DHA_PLOTS.length;i++) if(DHA_PLOTS[i].w * DHA_PLOTS[i].d === A) return DHA_PLOTS[i];
    return null;
  }

  // ── controls ──────────────────────────────────
  var citySel = document.getElementById("citySel"), authSel = document.getElementById("authSel");
  citySel.innerHTML = CITIES.map(function(c){ return '<option value="' + c.id + '">' + esc(c.label) + '</option>'; }).join("");
  authSel.innerHTML = AUTHS.map(function(a){ return '<option value="' + a.id + '">' + esc(a.label) + '</option>'; }).join("");
  citySel.value = state.city; authSel.value = state.auth;

  function resetShape(){
    state.over = {}; state.clear = 0; state.setback = 0; state.applied = null;
    if(!state.mumtyEdited) state.mumty = defMumty(state.w * state.d);
  }

  citySel.addEventListener("change", function(){ state.city = citySel.value; renderAll(); });
  authSel.addEventListener("change", function(){
    state.auth = authSel.value;
    state.cov = extend(authObj().cov, {});
    resetShape();
    renderAll();
  });

  var chips = document.getElementById("plotChips");
  PRESETS.forEach(function(p){
    var b = document.createElement("button");
    b.className = "chip"; b.type = "button"; b.textContent = p.label;
    b.setAttribute("data-v", p.id);
    b.addEventListener("click", function(){
      state.preset = p.id; state.w = p.w; state.d = p.d;
      resetShape();
      renderAll();
    });
    chips.appendChild(b);
  });

  [["cW","w"],["cD","d"]].forEach(function(pair){
    var el = document.getElementById(pair[0]);
    el.addEventListener("input", function(){
      var v = parseFloat(el.value), ok = isFinite(v) && v > 0;
      el.style.borderColor = ok ? "" : "#B3261E";
      if(!ok) return;           // the estimate keeps the last valid dimension until a positive value is typed
      state[pair[1]] = v;
      state.preset = null;
      resetShape();
      renderAll();
    });
  });

  // coverage rule inputs
  var COV_FIELDS = [["cvB","bmt",100],["cvG","g",100],["cvU","u",100],["cvM","mz",100],["cvV","ver",30]];
  COV_FIELDS.forEach(function(f){
    document.getElementById(f[0]).addEventListener("input", function(e){
      var v = parseFloat(e.target.value);
      if(!isFinite(v)) return;
      state.cov = extend(state.cov, {}); state.cov[f[1]] = Math.max(0, Math.min(f[2], v));
      // a typed coverage replaces the DHA piled-basement / road set-back geometry for that floor
      if(f[1] === "bmt") state.clear = 0;
      if(f[1] === "g") state.setback = 0;
      state.applied = null;
      renderAll();
    });
  });
  document.getElementById("cvMt").addEventListener("input", function(e){
    var v = parseFloat(e.target.value);
    if(!isFinite(v)) return;
    state.mumty = Math.max(0, v); state.mumtyEdited = true;
    renderAll();
  });

  function onSeg(id, fn){
    var el = document.getElementById(id);
    el.addEventListener("click", function(e){
      var b = e.target.closest("button");
      if(!b || !el.contains(b) || b.disabled) return;
      fn(b.getAttribute("data-v"));
    });
  }
  function pressSeg(id, val){
    Array.prototype.forEach.call(document.getElementById(id).querySelectorAll("button"), function(b){
      b.setAttribute("aria-pressed", b.getAttribute("data-v") === String(val) ? "true" : "false");
    });
  }

  onSeg("mezSeg", function(v){ state.m = v === "1"; state.applied = null; pruneOver(); renderAll(); });
  onSeg("bmtUseSeg", function(v){ state.bmtUse = v; render(); });
  onSeg("scopeSeg", function(v){ state.scope = v; if(v === "none") state.design = true; renderAll(); });
  onSeg("levelSeg", function(v){ state.level = v; render(); });
  onSeg("designSeg", function(v){ state.design = v === "1"; renderAll(); });
  onSeg("rateSeg", function(v){
    var toCustom = v === "custom";
    if(toCustom && !state.customRates){
      // start manual entry from the rates currently shown for the city
      state.rates = cityRates(cityObj());
      RATE_FIELDS.forEach(function(f){ document.getElementById("r_" + f[0]).value = state.rates[f[0]]; });
    }
    state.customRates = toCustom;
    document.getElementById("rateWrap").hidden = !toCustom;
    renderAll();
  });

  // drop typed areas for floors that no longer exist, so they cannot reappear later
  function pruneOver(){
    var keys = rowsOf(cfgNow()).map(function(r){ return r.k; });
    Object.keys(state.over).forEach(function(k){ if(keys.indexOf(k) === -1) delete state.over[k]; });
  }

  // basement and floor counts — buttons or typed
  function setCount(k, v){
    state[k] = Math.max(0, Math.min(MAX[k], Math.round(v)));
    state.applied = null;
    pruneOver();
  }
  Array.prototype.forEach.call(document.querySelectorAll(".stepper"), function(st){
    var k = st.getAttribute("data-k");
    st.addEventListener("click", function(e){
      var b = e.target.closest("button");
      if(!b || b.disabled) return;
      setCount(k, state[k] + parseInt(b.getAttribute("data-d"), 10));
      renderAll();
    });
    st.querySelector("input").addEventListener("input", function(e){
      var v = parseFloat(e.target.value);
      if(!isFinite(v)) return;
      setCount(k, v);
      renderAll();
    });
  });

  // one-click DHA allowance for a matching plot
  document.getElementById("bylawAdvice").addEventListener("click", function(e){
    var b = e.target.closest("button[data-ph]");
    var p = dhaMatch();
    if(!b || !p) return;
    var ph = byId(p.phases, b.getAttribute("data-ph"));
    state.cov = extend(AUTHS[0].cov, {});
    state.b = ph.b; state.m = ph.m; state.u = ph.u;
    state.over = {}; state.clear = ph.clear || 0; state.setback = ph.setback || 0;
    state.applied = "DHA " + ph.label + " allowance — " + configStr(ph.b, ph.m, ph.u) + ", max height " + ph.h;
    state.appliedPh = ph.id;
    renderAll();
  });

  document.getElementById("lmrChk").addEventListener("change", function(e){ state.lmr = e.target.checked; pruneOver(); renderAll(); });
  document.getElementById("resetAreas").addEventListener("click", function(){ state.over = {}; renderAll(); });

  // manual rate inputs
  var RATE_FIELDS = [
    ["g","Gray — above ground"],["bg","Basement gray"],["mg","Mumty and machine room gray"],["sc","Shell & core finishing"],
    ["fs","Standard finishing"],["fp","Premium finishing"],["bp","Basement finishing — parking"]
  ];
  var DR_FIELDS = [["sft","Design fee (Rs / SFT)"],["min","Design minimum fee (Rs)"]];
  var rateGrid = document.getElementById("rateGrid");
  RATE_FIELDS.concat(DR_FIELDS).forEach(function(f, i){
    var isD = i >= RATE_FIELDS.length;
    var d = document.createElement("div");
    d.innerHTML = '<label class="ctrl-label" for="r_'+f[0]+'">'+esc(f[1])+'</label>'+
      '<input type="number" id="r_'+f[0]+'" min="0" step="any" value="'+(isD ? state.dr : state.rates)[f[0]]+'" inputmode="decimal">';
    rateGrid.appendChild(d);
    d.querySelector("input").addEventListener("input", function(e){
      var v = parseFloat(e.target.value), store = isD ? state.dr : state.rates;
      var ok = e.target.value !== "" && isFinite(v) && v >= 0;
      e.target.style.borderColor = ok ? "" : "#B3261E";
      if(!ok) return;           // a blank or invalid rate never becomes Rs 0 — the last valid rate stays in use
      store[f[0]] = v;
      render();
    });
  });

  // add-on rows are built once so typing never loses focus
  var addonList = document.getElementById("addonList");
  ADDONS.forEach(function(ad){
    var s = state.ads[ad.id], row = document.createElement("div");
    row.className = "addon"; row.id = "ad-" + ad.id;
    row.innerHTML =
      '<label class="chk"><input type="checkbox" data-a="on"> ' + esc(ad.label) + '</label>' +
      '<span class="why" data-a="why" hidden>' + esc(ad.why || "") + '</span>' +
      '<div class="ad-body" data-a="body" hidden>' +
        (ad.opts ? '<div class="full"><select class="sel" data-a="opt">' + ad.opts.map(function(o){
          return '<option value="' + o.k + '"' + (o.k === s.opt ? ' selected' : '') + '>' + esc(o.label) + ' — ' + rs(o.rate) + '</option>';
        }).join("") + '</select></div>' : '') +
        '<div><span class="mini">Quantity (' + esc(ad.unit) + ')</span><input type="number" min="0" step="any" data-a="qty" inputmode="decimal"></div>' +
        '<div><span class="mini">Rate (Rs / ' + esc(ad.short) + ')</span><input type="number" min="0" step="any" data-a="rate" inputmode="decimal"></div>' +
        '<div class="full ad-amt"><span data-a="amt">—</span><span class="mini" data-a="note"></span></div>' +
      '</div>';
    addonList.appendChild(row);
    var q = function(a){ return row.querySelector('[data-a="' + a + '"]'); };
    q("on").addEventListener("change", function(e){ s.on = e.target.checked; q("body").hidden = !s.on; render(); });
    if(ad.opts) q("opt").addEventListener("change", function(e){ s.opt = e.target.value; s.rate = null; render(); });
    ["qty","rate"].forEach(function(k){
      q(k).addEventListener("input", function(e){
        var v = parseFloat(e.target.value);
        s[k] = (e.target.value === "" || !isFinite(v)) ? null : Math.max(0, v);
        render();
      });
    });
  });

  function updateAddons(cfg, c){
    var x = addonCtx(cfg, c);
    ADDONS.forEach(function(ad){
      var s = state.ads[ad.id], row = document.getElementById("ad-" + ad.id);
      var q = function(a){ return row.querySelector('[data-a="' + a + '"]'); };
      var ok = !ad.avail || ad.avail(x);
      row.classList.toggle("off", !ok);
      q("on").disabled = !ok;
      q("why").hidden = ok;
      q("body").hidden = !(s.on && ok);
      if(!ok) return;
      var opt = ad.opts ? optOf(ad, s.opt) : null;
      var qty = (s.qty != null) ? s.qty : ad.auto(x);
      var rate = (s.rate != null) ? s.rate : (opt ? opt.rate : ad.rate);
      if(document.activeElement !== q("qty")) q("qty").value = Math.round(qty * 100) / 100;
      if(document.activeElement !== q("rate")) q("rate").value = rate;
      q("amt").textContent = rs(qty * rate);
      q("note").textContent = ad.noteFn ? ad.noteFn(x) : (ad.note || "");
    });
  }

  // ── rendering ─────────────────────────────────
  function setVal(id, v){ var el = document.getElementById(id); if(document.activeElement !== el) el.value = v; }

  function renderControls(){
    var auth = authObj(), city = cityObj(), A = state.w * state.d;
    citySel.value = state.city; authSel.value = state.auth;
    document.getElementById("authNote").textContent = auth.note +
      (city.est ? " No city rate index was found for " + city.label + " — Lahore rates are applied; enter rates manually if your market differs." : "");

    Array.prototype.forEach.call(chips.children, function(c){
      c.setAttribute("aria-pressed", c.getAttribute("data-v") === state.preset ? "true" : "false");
    });
    setVal("cW", state.w); setVal("cD", state.d);
    document.getElementById("plotArea").textContent = fmt(A) + " SFT · " + sizeName(A) + " · " + fmt(A / 9) + " sq yd";

    setVal("vB", state.b); setVal("vU", state.u);
    Array.prototype.forEach.call(document.querySelectorAll(".stepper"), function(st){
      var k = st.getAttribute("data-k"), btns = st.querySelectorAll("button");
      btns[0].disabled = state[k] <= 0;
      btns[1].disabled = state[k] >= MAX[k];
    });
    pressSeg("mezSeg", state.m ? "1" : "0");
    document.getElementById("lmrChk").checked = state.lmr;
    document.getElementById("cfgHint").textContent = configStr(state.b, state.m, state.u) + " — " +
      (state.applied ? state.applied + "." : "check basements, floors and height against your approved plan.");

    // bylaw advice: one-click DHA allowances, or the authority's floor rules
    var adv = document.getElementById("bylawAdvice"), p = dhaMatch();
    if(auth.id === "dha" && p){
      adv.innerHTML = '<b>DHA Lahore allowance for ' + esc(p.label) + '</b>' + (p.assumed ? ' <span class="badge">Assumed</span>' : '') +
        '<div class="opts">' + p.phases.map(function(ph){
          var on = state.applied && state.appliedPh === ph.id;
          return '<button type="button" data-ph="' + ph.id + '" aria-pressed="' + (on ? "true" : "false") + '">' + esc(ph.label) +
                 '<span>' + configStr(ph.b, ph.m, ph.u) + ' · ' + esc(ph.h) + '</span></button>';
        }).join("") + '</div>' +
        ((p.assumed || p.note) ? '<div style="margin-top:8px;font-size:12px">' + esc([p.assumed, p.note].filter(Boolean).join(" ")) + '</div>' : '');
    } else if(auth.id === "dha"){
      adv.innerHTML = '<b>Not a standard DHA commercial size.</b> DHA commercial plots are 4, 8 and 32 Marla, or amalgamations of them. Enter the floors on your approved plan.';
    } else {
      adv.innerHTML = '<b>' + esc(auth.label) + ' — floors and height</b><br>' + esc(auth.floors) + (auth.assumed ? ' <span class="badge">Confirm locally</span>' : '');
    }

    setVal("cvB", num(state.cov.bmt)); setVal("cvG", num(state.cov.g)); setVal("cvU", num(state.cov.u));
    setVal("cvM", num(state.cov.mz)); setVal("cvV", num(state.cov.ver)); setVal("cvMt", num(state.mumty));

    document.getElementById("bmtUseField").hidden = state.b === 0 || state.scope === "none" || state.scope === "gray";
    pressSeg("bmtUseSeg", state.bmtUse);
    pressSeg("scopeSeg", state.scope);
    document.getElementById("levelField").hidden = state.scope !== "turnkey";
    pressSeg("levelSeg", state.level);
    pressSeg("designSeg", state.design ? "1" : "0");
    document.querySelector('#designSeg [data-v="0"]').disabled = state.scope === "none";
    document.getElementById("dHint").hidden = !state.design;
    pressSeg("rateSeg", state.customRates ? "custom" : "std");
    var cr = cityRates(city);
    document.getElementById("rateHint").textContent = state.customRates ? ""
      : (city.id === "lhr" || city.est)
        ? "Lahore 2026 rates: gray Rs " + fmt(cr.g) + ", basement Rs " + fmt(cr.bg) + ", finishing Rs " + fmt(cr.sc) + " / " + fmt(cr.fs) + " / " + fmt(cr.fp) + " per SFT."
        : city.label + " rates: gray Rs " + fmt(cr.g) + ", basement Rs " + fmt(cr.bg) + ", finishing Rs " + fmt(cr.sc) + " / " + fmt(cr.fs) + " / " + fmt(cr.fp) + " per SFT (" + city.why.toLowerCase() + ").";
  }

  function renderFloors(){
    var rows = rowsOf(cfgNow()), tb = document.getElementById("floorBody");
    tb.innerHTML = "";
    rows.forEach(function(r){
      var tr = document.createElement("tr");
      if(state.over[r.k] != null && state.over[r.k] !== r.def) tr.className = "edited";
      tr.innerHTML = '<td class="name">' + esc(r.label) + '<span class="r">' + esc(r.rule) + ' · ' + fmt(r.def) + '</span></td>' +
        '<td class="num"><input type="number" min="0" step="any" inputmode="decimal" aria-label="' + esc(r.label) + ' area" value="' + (Math.round(r.area * 100) / 100) + '"></td>';
      tr.querySelector("input").addEventListener("input", function(e){
        var v = parseFloat(e.target.value);
        if(e.target.value === "") delete state.over[r.k];
        else state.over[r.k] = (isFinite(v) && v >= 0) ? v : 0;
        tr.className = (state.over[r.k] != null && state.over[r.k] !== r.def) ? "edited" : "";
        render();
      });
      tb.appendChild(tr);
    });
  }

  function render(){
    var e = estimate(cfgNow()), cfg = e.cfg, c = {gray:e.gray, fin:e.fin, build:e.build, a:e.a};
    var ads = e.ads, fee = e.fee, dur = e.dur, addT = e.addT, contract = e.contract, feeT = e.feeT, total = e.total, a = e.a;
    document.getElementById("calcWarn").textContent = e.warnings.length ? "Check inputs: " + e.warnings.join(" · ") + "." : "";

    document.getElementById("floorTotal").textContent = sft(a.total);
    document.getElementById("floorBreak").textContent = "Total" + (a.bmt ? " — " + fmt(a.bmt) + " basement + " + fmt(a.up + a.roof) + " above ground" : "");

    document.getElementById("oArea").textContent = sft(a.total);
    document.getElementById("oAreaBreak").textContent = configStr(cfg.b, cfg.m, cfg.u) + " · " + cfg.city.label.toUpperCase() + (a.bmt ? " · " + fmt(a.bmt) + " BASEMENT" : "");

    var hasG = cfg.scope !== "none", hasF = cfg.scope === "shell" || cfg.scope === "turnkey";
    document.getElementById("oGray").textContent = hasG ? rs(c.gray) : "— not in scope";
    document.getElementById("oGray").className = "v" + (hasG ? "" : " muted");
    document.getElementById("lGray").textContent = hasG
      ? "@ RS " + fmt(cfg.rates.g) + " · BASEMENT " + fmt(cfg.rates.bg) + " · ROOF " + fmt(cfg.rates.mg)
      : "NOT IN SCOPE";
    var f = finRates(cfg);
    document.getElementById("kFin").textContent = hasF ? levelName(cfg) : "Finishing";
    document.getElementById("oFin").textContent = hasF ? rs(c.fin) : "— not in scope";
    document.getElementById("oFin").className = "v" + (hasF ? "" : " muted");
    document.getElementById("lFin").textContent = hasF
      ? "@ RS " + fmt(f.up) + (a.bmt ? " · BASEMENT " + fmt(f.bmt) : "") + " · ROOF " + fmt(f.roof)
      : "NOT IN SCOPE";
    document.getElementById("oAdd").textContent = ads.length ? rs(addT) : hasG ? "— none selected" : "— not applicable";
    document.getElementById("oAdd").className = "v" + (ads.length ? "" : " muted");
    document.getElementById("lAdd").textContent = ads.length ? ads.length + (ads.length > 1 ? " ITEMS" : " ITEM") : hasG ? "SELECT BELOW" : "CONSTRUCTION SCOPES ONLY";
    document.getElementById("oDes").textContent = fee ? rs(fee.fee) : "— not included";
    document.getElementById("oDes").className = "v" + (fee ? "" : " muted");
    document.getElementById("lDes").textContent = !fee ? "NOT INCLUDED"
      : fee.atMin ? "MINIMUM FEE" : qty(a.total) + " SFT @ RS " + qty(cfg.dr.sft);

    document.getElementById("dHint").textContent = !fee ? "" :
      qty(a.total) + " SFT × Rs " + qty(cfg.dr.sft) + " per SFT = " + rs(fee.raw) + ", minimum " + rs(cfg.dr.min) + "." +
      (fee.atMin ? " The minimum applies." : "");

    document.getElementById("oDur").textContent = (hasG ? dur.total : dur.pre) + " days";
    document.getElementById("oDurBreak").textContent = hasG
      ? dur.gray + " GRAY" + (dur.bmt ? " (INCL. " + dur.bmt + " BASEMENT)" : "") + (dur.fin ? " + " + dur.fin + (cfg.scope === "shell" ? " SHELL & CORE" : " FINISHING") : "")
        + " · ≈ " + months(dur.total) + " MONTHS" + (fee ? " · PLUS ≈ " + months(dur.pre) + " MONTHS DESIGN & APPROVAL" : "")
      : "DESIGN AND APPROVAL";

    var parts = [c.gray, c.fin, addT, feeT];
    ["barG","barF","barA","barD"].forEach(function(id, i){
      document.getElementById(id).style.width = (total ? parts[i] / total * 100 : 0) + "%";
    });

    document.getElementById("totalLabel").textContent =
      cfg.scope === "none" ? "Design services fee"
      : (cfg.scope === "gray" ? "Gray structure" : cfg.scope === "shell" ? "Shell & core" : "Turnkey") + (fee ? " + design" : "") + " — total";
    document.getElementById("oTotal").textContent = rs(total);
    document.getElementById("oAlt").textContent = total
      ? words(total) + (c.build && a.total ? "   ·   Rs " + fmt(c.build / a.total) + " / SFT blended construction" : "")
      : "";

    updateAddons(cfg, c);
    renderPayments(cfg, contract, fee);
    renderCostTable();
    drawPlot(cfg);
  }

  function renderAll(){ renderControls(); renderFloors(); render(); }

  function payRowsHtml(stages, total){
    var amts = stageAmounts(total, stages);
    return stages.map(function(st, i){
      return '<tr><td class="num">' + (i + 1) + '</td><td class="name" style="white-space:normal">' + esc(st[0]) + '</td>' +
        '<td class="num">' + pctTxt(st[1]) + '</td><td class="num">' + (total ? rs(amts[i]) : "—") + '</td></tr>';
    }).join("");
  }

  function renderPayments(cfg, contract, fee){
    var stages = payStages(cfg), tb = document.getElementById("payBody");
    tb.innerHTML = stages.length ? payRowsHtml(stages, contract)
      : '<tr><td colspan="4" style="text-align:center;color:#5A6B82;padding:18px">Design only — no construction contract selected.</td></tr>';
    document.getElementById("payTotal").textContent = stages.length ? rs(contract) : "—";
    var scopeName = cfg.scope === "gray" ? "gray structure" : cfg.scope === "shell" ? "shell & core" : "turnkey";
    document.getElementById("payBasis").textContent = stages.length
      ? "Based on a " + scopeName + " contract for a " + configStr(cfg.b, cfg.m, cfg.u) + " plaza on a " + cfg.label +
        " plot (" + num(cfg.w) + "' × " + num(cfg.d) + "') in " + cfg.city.label + " — " + rs(contract) + " including selected add-ons. Adjust the estimator to reprice."
      : "Select a construction scope in the estimator to build the schedule.";

    var dFee = (fee || designFeeOf(costOf(cfg).a.total, cfg.dr)).fee;
    document.getElementById("dPayBody").innerHTML = payRowsHtml(DESIGN_STAGES, dFee);
    document.getElementById("dPayTotal").textContent = rs(dFee);
    document.getElementById("dPayBasis").textContent = fee
      ? "Design fee for the plaza in the estimator — " + rs(dFee) + "."
      : "Design is not selected in the estimator; amounts show the fee for its covered area at Rs " + fmt(cfg.dr.sft) + " per SFT.";
  }

  // ── reference tables ──────────────────────────
  function dhaRows(fn){
    DHA_PLOTS.forEach(function(p){ p.phases.forEach(function(ph, i){ fn(p, ph, i); }); });
  }

  function renderAuthTable(){
    document.getElementById("authBody").innerHTML = AUTHS.map(function(a){
      var c = a.cov;
      return '<tr><td class="name">' + esc(a.label) + (a.assumed ? '<br><span class="badge" style="margin:4px 0 0">Assumed in part</span>' : '') + '</td>' +
        '<td class="num">' + num(c.bmt) + '%</td><td class="num">' + num(c.g) + '%</td>' +
        '<td class="num">' + num(c.mz) + '%' + (c.ver ? '<br><span style="color:#5A6B82;font-size:12px">excl. ' + c.ver + ' ft verandah</span>' : '') + '</td>' +
        '<td class="num">' + num(c.u) + '%</td><td style="font-size:13.5px">' + esc(a.floors) + '</td></tr>';
    }).join("");
  }

  function renderCityTable(){
    var pct = function(k){ var v = Math.round((k - 1) * 1000) / 10; return v === 0 ? "—" : (v > 0 ? "+" : "") + v + "%"; };
    document.getElementById("cityBody").innerHTML = CITIES.filter(function(c){ return !c.est; }).map(function(c){
      return '<tr><td class="name">' + esc(c.label) + '</td><td class="num">' + pct(c.f.g) + '</td><td class="num">' + pct(c.f.fin) + '</td>' +
        '<td class="num">' + pct(c.f.b) + '</td><td style="font-size:13.5px">' + esc(c.why) + '</td></tr>';
    }).join("") + '<tr><td class="name">Faisalabad, Multan, Gujranwala, Sialkot, Peshawar, others</td><td class="num">—</td><td class="num">—</td><td class="num">—</td>' +
      '<td style="font-size:13.5px">No published index found — Lahore rates applied <span class="badge">Assumed</span></td></tr>';
  }

  function renderBylawTable(){
    var html = "";
    dhaRows(function(p, ph, i){
      var a = sumAreas(rowsOf(dhaCfg(p, ph)));
      html += '<tr>' +
