  function drawPlot(cfg){
    var D = dims(cfg), svg = document.getElementById("plotSVG");
    var W = 360, H = 230, padL = 46, padT = 30, padR = 18, padB = 48;
    var availW = W - padL - padR, availH = H - padT - padB;
    var scale = Math.min(availW / D.w, availH / D.d);
    var w = D.w * scale, h = D.d * scale;
    var x = padL + (availW - w) / 2, y = padT + (availH - h) / 2;
    var stripFt = cfg.setback || cfg.cov.ver, sh = Math.max(stripFt * scale, 3);
    var stripLbl = cfg.setback ? "PARKING SET-BACK " + stripFt + "'" : "VERANDAH " + num(stripFt) + "'";
    svg.innerHTML =
      '<title>Plot dimension drawing</title>' +
      '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" fill="#EAF1FA" stroke="#003478" stroke-width="1.5"/>' +
      (stripFt ? '<rect x="' + x + '" y="' + (y + h - sh) + '" width="' + w + '" height="' + sh + '" fill="#C9D8EC" stroke="#1A6FC4" stroke-width="1" stroke-dasharray="4 3"/>' +
        (sh >= 11 && w >= 90 ? '<text x="' + (x + w/2) + '" y="' + (y + h - sh/2 + 3.5) + '" text-anchor="middle" font-family="IBM Plex Mono, monospace" font-size="9" fill="#003478">' + stripLbl + '</text>' : '') : '') +
      // frontage dimension
      '<line x1="' + x + '" y1="' + (y - 14) + '" x2="' + (x + w) + '" y2="' + (y - 14) + '" stroke="#1A6FC4" stroke-width="1"/>' +
      '<line x1="' + x + '" y1="' + (y - 19) + '" x2="' + x + '" y2="' + (y - 9) + '" stroke="#1A6FC4" stroke-width="1"/>' +
      '<line x1="' + (x + w) + '" y1="' + (y - 19) + '" x2="' + (x + w) + '" y2="' + (y - 9) + '" stroke="#1A6FC4" stroke-width="1"/>' +
      '<text x="' + (x + w/2) + '" y="' + (y - 20) + '" text-anchor="middle" font-family="IBM Plex Mono, monospace" font-size="11" fill="#003478">' + num(D.w) + "' FRONTAGE</text>" +
      // depth dimension
      '<line x1="' + (x - 18) + '" y1="' + y + '" x2="' + (x - 18) + '" y2="' + (y + h) + '" stroke="#1A6FC4" stroke-width="1"/>' +
      '<line x1="' + (x - 23) + '" y1="' + y + '" x2="' + (x - 13) + '" y2="' + y + '" stroke="#1A6FC4" stroke-width="1"/>' +
      '<line x1="' + (x - 23) + '" y1="' + (y + h) + '" x2="' + (x - 13) + '" y2="' + (y + h) + '" stroke="#1A6FC4" stroke-width="1"/>' +
      '<text x="' + (x - 26) + '" y="' + (y + h/2) + '" text-anchor="middle" transform="rotate(-90 ' + (x - 26) + ' ' + (y + h/2) + ')" font-family="IBM Plex Mono, monospace" font-size="11" fill="#003478">' + num(D.d) + "'</text>" +
      // road
      '<line x1="' + (padL - 10) + '" y1="' + (y + h + 9) + '" x2="' + (W - padR + 6) + '" y2="' + (y + h + 9) + '" stroke="#8B9AAE" stroke-width="1" stroke-dasharray="6 4"/>' +
      '<text x="' + (x + w/2) + '" y="' + (y + h + 21) + '" text-anchor="middle" font-family="IBM Plex Mono, monospace" font-size="9.5" fill="#8B9AAE">ROAD</text>' +
      '<text x="180" y="225" text-anchor="middle" font-family="IBM Plex Mono, monospace" font-size="10.5" fill="#5A6B82">' + esc(cfg.label.toUpperCase()) + ' · ' + fmt(D.A) + ' SFT PLOT AREA</text>';
  }

