  // ══ QUOTATION GENERATOR ═══════════════════════════════
  var LOGO = "data:image/png;base64,";

  var ONES = ["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve",
    "Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];
  var TENS = ["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];

  function twoDigit(n){
    if(n < 20) return ONES[n];
    return TENS[Math.floor(n/10)] + (n%10 ? " " + ONES[n%10] : "");
  }
  function threeDigit(n){
    var out = "";
    if(n > 99){ out += ONES[Math.floor(n/100)] + " Hundred"; n %= 100; if(n) out += " "; }
    if(n) out += twoDigit(n);
    return out;
  }
  // Pakistani numbering: crore / lakh / thousand / hundred
  function inWords(num){
    num = Math.round(num);
    if(num === 0) return "Rupees Zero Only";
    var parts = [];
    var crore = Math.floor(num/10000000); num %= 10000000;
    var lakh  = Math.floor(num/100000);   num %= 100000;
    var thou  = Math.floor(num/1000);     num %= 1000;
    if(crore) parts.push(threeDigit(crore) + " Crore");
    if(lakh)  parts.push(twoDigit(lakh) + " Lakh");
    if(thou)  parts.push(twoDigit(thou) + " Thousand");
    if(num)   parts.push(threeDigit(num));
    return "Rupees " + parts.join(" ") + " Only";
  }

  var MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
  function dateTxt(d){ return d.getDate() + " " + MONTHS[d.getMonth()] + " " + d.getFullYear(); }
  function today(){ return dateTxt(new Date()); }
  function validTill(){ var d = new Date(); d.setDate(d.getDate() + 30); return dateTxt(d); }
  function refNo(){
    var d = new Date();
    var p = function(x){ return (x<10?"0":"") + x; };
    return "ACCO/CP/" + d.getFullYear() + "/" + p(d.getMonth()+1) + p(d.getDate()) + "-" +
           String(Math.floor(Math.random()*900)+100);
  }

