      ["Power", [["trans","transformer and substation"],["gen","diesel generator"],["solar","solar PV system"],[null,"UPS and stabilisers"]]],
      ["Building services", [["vrf","central HVAC / VRF (split AC provisions only)"],["tanks","water tanks beyond the gray structure"],["cctv","CCTV and access control"],[null,"BMS and IT / data networks"]]]
