      '<tr><td ' + k + '>Completion period</td><td colspan="3">' + (hasG
          ? '<b>' + dur.total + ' days</b> from mobilisation (&asymp; ' + months(dur.total) + ' months)' + (fee ? ', after about ' + months(dur.pre) + ' months of design and approval' : '')
          : '<b>About ' + months(dur.pre) + ' months</b> for design and approval') + '</td></tr>' +
      '</tbody></table></div>';

    // ── covered area schedule
    var html2 = head("Covered area schedule") + '<table class="qt"><thead><tr><th>Floor</th><th>Basis</th><th class="n">Area (SFT)</th></tr></thead><tbody>' +
      c.rows.map(function(r){
        return '<tr><td>' + esc(r.label) + '</td><td>' + (r.area !== r.def ? 'As designed' : esc(r.rule)) + '</td><td class="n">' + qty(r.area) + '</td></tr>';
      }).join("") +
      '<tr class="sub"><td colspan="2">TOTAL COVERED AREA</td><td class="n">' + qty(a.total) + '</td></tr></tbody></table>' +
      '<div class="inwords" style="border-top:0"><b>Note</b>Floors and coverage are as entered for ' + esc(place) + ' and are re-measured from the approved drawings before the contract.</div></div>';

    // ── cost summary
    var rowsH = "", sr = 0;
    c.L.forEach(function(l){
      sr++;
      rowsH += '<tr><td class="c">' + sr + '</td><td><b>' + esc(l.label) + '</b><br><span class="qd">' + esc(l.desc) + '</span></td>' +
        '<td class="n">' + qty(l.qty) + ' SFT</td><td class="n">' + qty(l.rate) + '</td><td class="n">' + rs(l.amt) + '</td></tr>';
    });
    ads.forEach(function(l){
      sr++;
      rowsH += '<tr><td class="c">' + sr + '</td><td><b>' + esc(l.label) + '</b><br><span class="qd">Add-on, supply and install</span></td>' +
        '<td class="n">' + qty(l.qty) + ' ' + esc(l.short) + '</td><td class="n">' + qty(l.rate) + '</td><td class="n">' + rs(l.amt) + '</td></tr>';
    });
    if(contract && fee) rowsH += '<tr class="sub"><td colspan="4">CONSTRUCTION CONTRACT VALUE</td><td class="n">' + rs(contract) + '</td></tr>';
    if(fee){
      sr++;
      rowsH += '<tr><td class="c">' + sr + '</td><td><b>Design services — architecture, structure, MEP and 3D</b><br><span class="qd">' +
        (fee.atMin ? 'Minimum design fee — ' + qty(a.total) + ' SFT at Rs ' + qty(cfg.dr.sft) + ' would be ' + rs(fee.raw) : 'Per SFT of total covered area') + '</span></td>' +
        '<td class="n">' + (fee.atMin ? '—' : qty(a.total) + ' SFT') + '</td>' +
        '<td class="n">' + (fee.atMin ? '—' : qty(cfg.dr.sft)) + '</td><td class="n">' + rs(fee.fee) + '</td></tr>';
    }
    var html3 = head("Cost summary") +
      '<table class="qt"><thead><tr><th class="c">SR</th><th>Description</th><th class="n">Quantity</th><th class="n">Rate (Rs)</th><th class="n">Amount (Rs)</th></tr></thead>' +
      '<tbody>' + rowsH + '<tr class="grand"><td colspan="4">' + (fee && contract ? 'PRELIMINARY PROJECT TOTAL — CONSTRUCTION + DESIGN' : fee ? 'PRELIMINARY DESIGN FEE' : 'PRELIMINARY CONSTRUCTION CONTRACT VALUE') + '</td><td class="n">' + rs(total) + '</td></tr></tbody></table>' +
      '<div class="inwords"><b>In words</b>' + inWords(total) + '</div></div>';

    // ── payment schedule
    var stages = e.stages, html4 = head("Payment schedule");
    if(stages.length){
      var amts = e.payAmts;
      html4 += '<table class="qt"><thead><tr><th class="c">SR</th><th>Construction stage</th><th class="n">%age</th><th class="n">Amount (Rs)</th></tr></thead><tbody>' +
        stages.map(function(st, i){ return '<tr><td class="c">' + (i + 1) + '</td><td>' + esc(st[0]) + '</td><td class="n">' + pctTxt(st[1]) + '</td><td class="n">' + rs(amts[i]) + '</td></tr>'; }).join("") +
        '<tr class="sub"><td class="c">—</td><td>TOTAL CONSTRUCTION</td><td class="n">100%</td><td class="n">' + rs(contract) + '</td></tr></tbody></table>';
    }
    if(fee){
      var damts = e.dAmts;
      html4 += '<table class="qt"' + (stages.length ? ' style="margin-top:8px"' : '') + '><thead><tr><th class="c">SR</th><th>Design stage</th><th class="n">%age</th><th class="n">Amount (Rs)</th></tr></thead><tbody>' +
        DESIGN_STAGES.map(function(st, i){ return '<tr><td class="c">' + (i + 1) + '</td><td>' + esc(st[0]) + '</td><td class="n">' + st[1] + '%</td><td class="n">' + rs(damts[i]) + '</td></tr>'; }).join("") +
        '<tr class="sub"><td class="c">—</td><td>TOTAL DESIGN FEE</td><td class="n">100%</td><td class="n">' + rs(fee.fee) + '</td></tr></tbody></table>';
    }
    html4 += '<div class="inwords" style="border-top:0"><b>Note</b>Each instalment falls due on completion of the stage against it, verified on site before invoicing. Add-ons are included in the construction instalments.</div></div>';

    // ── timeline
    var t = TL[D.cls];
    var html5 = head("Project timeline") + '<table class="qt"><thead><tr><th>Stage</th><th class="n">Duration</th><th>Remarks</th></tr></thead><tbody>' +
      (fee ? '<tr><td>Design and approval</td><td class="n">&asymp; ' + months(dur.pre) + ' months</td><td>Soil report, concept, 3D, submission set and scrutiny — before mobilisation</td></tr>' : '') +
      (hasG ? '<tr><td>Mobilisation and excavation</td><td class="n">' + t.mob + ' days</td><td>Site setup, excavation permission, shoring</td></tr>' : '') +
      (hasG && dur.bmt ? '<tr><td>Basement' + (cfg.b > 1 ? 's (' + cfg.b + ')' : '') + '</td><td class="n">' + dur.bmt + ' days</td><td>Raft, retaining walls, waterproofing and slab</td></tr>' : '') +
      (hasG ? '<tr><td>Superstructure</td><td class="n">' + (dur.gray - t.mob - dur.bmt) + ' days</td><td>Ground' + (cfg.m ? ', mezzanine' : '') + (cfg.u ? ' and ' + cfg.u + ' upper slab' + (cfg.u > 1 ? 's' : '') : '') + ', roof, mumty and machine room</td></tr>' : '') +
      (dur.fin ? '<tr><td>' + (cfg.scope === "shell" ? 'Shell &amp; core finishing' : 'Finishing') + '</td><td class="n">' + dur.fin + ' days</td><td>Starts on the lower floors while upper slabs are cast; ends with handover</td></tr>' : '') +
      (hasG ? '<tr class="sub"><td>TOTAL CONSTRUCTION DURATION</td><td class="n">' + dur.total + ' days</td><td>&asymp; ' + months(dur.total) + ' months from mobilisation</td></tr>' : '') +
      '</tbody></table>' +
      '<div class="inwords" style="border-top:0"><b>Note</b>Durations are in calendar days and assume timely payments, timely approval of drawings and material selections, and normal weather. RCC piling adds 20–30 days per basement.</div></div>';

    // ── design deliverables
    var html6 = fee ? head("Design services and deliverables") +
      '<div class="qcols" style="grid-template-columns:1fr"><div><ul class="qlist">' + DELIVERABLES.map(function(x){ return '<li>' + esc(x) + '</li>'; }).join("") + '</ul></div></div>' +
      '<div class="inwords" style="border-top:0"><b>Team</b>PCATP-registered architect and PEC consulting structural engineer.</div></div>' : '';

    // ── scope of work
    var col2 = "";
    if(hasF){
      var fin = cfg.scope === "shell" ? SHELL_SCOPE : SHELL_SCOPE.slice(0, -1).concat(FIN_STD, cfg.level === "prem" ? FIN_PREM : []);
      col2 = '<div><h4>' + esc(levelName(cfg)) + '</h4><ul class="qlist">' + fin.map(function(x){ return '<li>' + esc(x) + '</li>'; }).join("") + '</ul>' +
        (cfg.b > 0 && cfg.bmtUse === "park" ? '<h4 style="margin-top:9px">Basement — parking</h4><ul class="qlist">' + BMT_PARK.map(function(x){ return '<li>' + esc(x) + '</li>'; }).join("") + '</ul>' : '') + '</div>';
    }
    var html7 = hasG ? head("Scope of work") + '<div class="qcols"' + (hasF ? '' : ' style="grid-template-columns:1fr"') + '>' +
      '<div><h4>Gray structure</h4><ul class="qlist">' + GRAY_SCOPE.filter(function(x, i){ return cfg.b > 0 || [2,3,5,13].indexOf(i) === -1; }).map(function(x){ return '<li>' + esc(x) + '</li>'; }).join("") + '</ul></div>' +
      col2 + '</div></div>' : '';

    // ── material specification
    var spec = specRows(cfg, ads);
    var html8 = spec ? head("Material specification") + '<table class="spec"><tbody>' + spec + '</tbody></table>' +
      '<div class="inwords" style="margin-top:6px;border-top:1px solid #C9D6E6"><b>Note</b>Final brand selection within each approved category is made jointly with the client before procurement.</div></div>' : '';

    var html9  = head("Exclusions") + '<ol class="terms">' + exclusions(cfg, ads).map(function(x){ return '<li>' + esc(x) + '</li>'; }).join("") + '</ol></div>';
    var html10 = head("Terms and conditions") + '<ol class="terms">' + terms(cfg, ads).map(function(x){ return '<li>' + esc(x) + '</li>'; }).join("") + '</ol></div>';

    var html =
    '<div class="qhead">' +
      '<div class="lh">' +
        '<img src="' + LOGO + '" alt="Ahmed Construction Company">' +
        '<div class="co"><b>AHMED CONSTRUCTION COMPANY</b>' +
          '<span>Architecture &middot; Engineering &middot; Construction</span>' +
          'Office 2, 3rd Floor, Bigcity Plaza, Gulberg-III, Lahore<br>' +
          '0322-8000190 &nbsp;|&nbsp; info@acco.com.pk &nbsp;|&nbsp; acco.com.pk' +
          '<span class="qfor">Prepared for: ' + esc(client) + '</span></div>' +
      '</div><div class="lh-rule"></div>' +
    '</div>' +
    '<div class="qtitle"><div><h1>Preliminary Quotation — Commercial Plaza</h1>' +
      '<div class="sub">' + esc(scopeTitle(cfg)) + '</div></div>' +
      '<div class="qmeta"><b>Ref</b> ' + QREF + '<br><b>Date</b> ' + today() + '<br><b>Valid till</b> ' + validTill() + '</div></div>' +
    '<div class="qto">' +
      '<div><div class="lbl">Quotation for</div><div class="val">' + esc(client) + '</div></div>' +
      '<div><div class="lbl">Project site</div><div class="val">' + esc(site) + '</div></div>' +
    '</div>' +
    '<div class="inwords" style="border-top:1px solid #C9D6E6;margin:-6px 0 16px"><b>Preliminary estimate</b>Calculated from the floors, coverage and rates stated in this document. It is not a fixed-price offer; the contract amount is fixed only after a measured BOQ from the approved drawings.</div>' +
    html1 + html2 + html3 + html4 + html5 + html6 + html7 + html8 + html9 + html10 +
    '<div class="sign">' +
      '<div><div class="r">For Ahmed Construction Company</div><div class="s">Authorised signatory &nbsp;|&nbsp; Date</div></div>' +
      '<div><div class="r">Accepted by client</div><div class="s">Name, signature &amp; CNIC &nbsp;|&nbsp; Date</div></div>' +
    '</div>' +
    '<div class="qfoot"><span>Ahmed Construction Company (ACCO) &middot; Architecture, Engineering &amp; Construction &middot; 25+ years</span>' +
      '<span>Preliminary quotation — supersedes all previous verbal or written estimates for this project.</span></div>';

    document.getElementById("quoteDoc").innerHTML = html;
  }

  function showQuote(show){
    document.body.classList.toggle("quote-mode", show);
    document.getElementById("site").hidden = show;
    document.getElementById("quoteWrap").hidden = !show;
    window.scrollTo(0,0);
  }

  document.getElementById("qGen").addEventListener("click", function(){
    buildQuote();
    showQuote(true);
  });
  document.getElementById("qBack").addEventListener("click", function(){ showQuote(false); });

  // filename used for both save actions
  function quoteFileName(){
    var c = document.getElementById("qClient").value.trim()
              .replace(/[^A-Za-z0-9 ]/g,"").replace(/\s+/g,"-");
    return c || QREF.replace(/[^A-Za-z0-9]/g,"-");
  }

  function needClient(){
    if(document.getElementById("qClient").value.trim()) return false;
    showQuote(false);
    var el = document.getElementById("qClient");
    el.focus();
    el.style.borderColor = "#0057B8";
    el.placeholder = "Enter client name — used for the file name";
    return true;
  }

  // Save as PDF — names the file via document.title, then opens the print dialog
  document.getElementById("qPrint").addEventListener("click", function(){
    if(needClient()) return;
    var t = document.title;
    document.title = quoteFileName();
    window.print();
    setTimeout(function(){ document.title = t; }, 1200);
  });

  // Save copy — downloads the quotation as a standalone HTML file
  document.getElementById("qSaveCopy").addEventListener("click", function(){
    if(needClient()) return;
    var css = "";
    Array.prototype.forEach.call(document.querySelectorAll("style"), function(s){ css += s.textContent + "\n"; });
    var doc = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">' +
      '<meta name="viewport" content="width=device-width, initial-scale=1">' +
      '<title>' + quoteFileName() + '</title>' +
      '<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet">' +
      '<style>' + css +
        'body{margin:0;background:#E8EDF3}' +
        '@media print{@page{size:210mm 297mm portrait;margin:14mm 12mm 14mm 12mm}' +
        'html,body{background:#fff!important}.quote-stage{padding:0!important;background:#fff!important}' +
        '.quote-doc{width:auto!important;max-width:none!important;min-height:0!important;padding:0!important;box-shadow:none!important;font-size:10.2px}' +
        '.qhead{background:#fff}}' +
      '</style></head>' +
      '<body class="quote-mode"><div class="quote-stage"><div class="quote-doc">' +
      document.getElementById("quoteDoc").innerHTML +
      '</div></div></body></html>';
    var blob = new Blob([doc], {type:"text/html;charset=utf-8"});
    var url = URL.createObjectURL(blob);
    var link = document.createElement("a");
    link.href = url; link.download = quoteFileName() + ".html";
    document.body.appendChild(link); link.click(); document.body.removeChild(link);
    setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
  });

  renderAuthTable();
  renderCityTable();
  renderBylawTable();
  renderTimeTable();
  renderFaq();
  renderAll();
})();

</script>
</body>
</html>
